import React from 'react';
import { Package } from 'lucide-react';

const TopProducts = () => {
  const topProducts = [
    { name: 'Casque Premium', sales: 342, revenue: '$12,450', stock: 45 },
    { name: 'Souris sans fil', sales: 289, revenue: '$8,670', stock: 12 },
    { name: 'Support portable', sales: 156, revenue: '$5,460', stock: 23 },
  ];

  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-2xl p-6 shadow-lg border border-white/30 dark:border-neutral-800/50">
      <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-6">Produits populaires</h3>
      <div className="space-y-4">
        {topProducts.map((product, index) => (
          <div key={index} className="flex items-center justify-between p-3 rounded-xl hover:bg-neutral-50 dark:hover:bg-neutral-800/50 transition-colors">
            <div className="flex items-center space-x-3">
              <div className="h-10 w-10 rounded-lg bg-gradient-to-r from-primary-500/10 to-secondary-500/10 flex items-center justify-center">
                <Package className="h-5 w-5 text-primary-500" />
              </div>
              <div>
                <h4 className="font-medium text-neutral-900 dark:text-white">{product.name}</h4>
                <p className="text-xs text-neutral-500 dark:text-neutral-400">{product.sales} ventes</p>
              </div>
            </div>
            <div className="text-right">
              <p className="font-medium text-neutral-900 dark:text-white">{product.revenue}</p>
              <p className={`text-xs ${product.stock < 10 ? 'text-red-500' : 'text-accent-500'}`}>
                {product.stock} en stock
              </p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default TopProducts;
